package app.patchwork.radar;
import org.json.*;import org.junit.Test;import java.time.*;import java.util.*;import static org.junit.Assert.*;
public class BroadcastReminderTest {
 private final long NOW=Instant.parse("2026-10-23T03:00:00Z").toEpochMilli();
 private JSONObject p()throws Exception{return new JSONObject().put("enabled",true).put("locale","ja").put("games",new JSONArray().put("stellasora")).put("region","kr").put("kinds",new JSONArray()).put("broadcastsEnabled",true).put("broadcastOffsets",new JSONArray().put(15).put(0)).put("quietEnabled",false);}
 private JSONObject e()throws Exception{return new JSONObject().put("id","stella-stream").put("gameId","stellasora").put("region","global").put("kind","broadcast").put("expectedLocale","ja").put("startAt",JSONObject.NULL).put("endAt",JSONObject.NULL).put("title",new JSONObject().put("ja","公式番組")).put("broadcast",new JSONObject().put("official",true).put("metadataVerified",true).put("locale","ja").put("status","scheduled").put("youtubeId","abcdefghijk").put("verifiedAt",Instant.ofEpochMilli(NOW).toString()).put("scheduledAt",Instant.ofEpochMilli(NOW+3600000).toString()).put("programStartAt",Instant.ofEpochMilli(NOW+5400000).toString()));}
 private JSONObject f(JSONObject e)throws Exception{return new JSONObject().put("schemaVersion",1).put("games",new JSONArray().put(new JSONObject().put("id","stellasora").put("canonicalRegions",new JSONObject().put("kr","global")))).put("entries",new JSONArray()).put("broadcasts",new JSONArray().put(e));}
 @Test public void separateOptInUsesConfirmedProgramAndNeverWidgetDeadline()throws Exception{JSONObject e=e(),f=f(e),p=p();List<ReminderPolicy.Reminder> plan=ReminderPolicy.plan(f,p,NOW,ZoneId.of("UTC"));assertEquals(2,plan.size());assertEquals("broadcast",plan.get(0).event);assertEquals(NOW+4500000,plan.get(0).fireAt);assertTrue(ReminderPolicy.deadlines(f,p,NOW).isEmpty());assertTrue(WidgetPolicy.rows(f,p,NOW,true).isEmpty());p.put("broadcastsEnabled",false);assertTrue(ReminderPolicy.plan(f,p,NOW,ZoneId.of("UTC")).isEmpty());}
 @Test public void transmissionFallbackIsExplicitAndAllLanguagesUseBroadcastWording()throws Exception{JSONObject e=e(),p=p();e.getJSONObject("broadcast").remove("programStartAt");assertEquals(NOW+3600000,ReminderPolicy.eventAt(e,"broadcast"));for(String l:Arrays.asList("ko","en","ja","zh")){p.put("locale",l);ReminderMessage m=ReminderMessage.create(f(e),p,e,"broadcast",NOW+3600000,15,NOW,ZoneId.of("UTC"));assertFalse(m.creative);assertFalse(m.title.isEmpty());assertFalse(m.body.contains("Ends"));}}
 @Test public void cancelledEndedLiveUnverifiedAndStaleAreNeverScheduled()throws Exception{for(String status:Arrays.asList("cancelled","ended","live")){JSONObject e=e();e.getJSONObject("broadcast").put("status",status);assertTrue(ReminderPolicy.plan(f(e),p(),NOW,ZoneId.of("UTC")).isEmpty());}JSONObject e=e();e.getJSONObject("broadcast").put("metadataVerified",false);assertFalse(ReminderPolicy.broadcastEligible(e,NOW));e=e();e.getJSONObject("broadcast").put("statusCheckedAt",Instant.ofEpochMilli(NOW-25*3600000).toString());assertFalse(ReminderPolicy.broadcastEligible(e,NOW));}
 @Test public void servicesLanguageAndMyGamesStayIsolated()throws Exception{JSONObject e=e(),p=p();e.getJSONObject("broadcast").put("locale","ko");assertTrue(ReminderPolicy.plan(f(e),p,NOW,ZoneId.of("UTC")).isEmpty());e=e();p.put("games",new JSONArray());assertTrue(ReminderPolicy.plan(f(e),p,NOW,ZoneId.of("UTC")).isEmpty());e.put("region","jp");assertFalse(ReminderPolicy.matches(e,p(),f(e)));}
 @Test public void cancellationAndCorrectedTimeInvalidateDelivery()throws Exception{JSONObject e=e(),p=p();long at=ReminderPolicy.eventAt(e,"broadcast");assertTrue(ReminderSettings.due(e,p,"broadcast",at,15,at-15*60000));e.getJSONObject("broadcast").put("status","cancelled");assertFalse(ReminderSettings.due(e,p,"broadcast",at,15,at));e=e();e.getJSONObject("broadcast").put("programStartAt",Instant.ofEpochMilli(at+60000).toString());assertFalse(ReminderSettings.due(e,p,"broadcast",at,0,at));}
 @Test public void duplicateVideosDeduplicateAndDateOnlyCannotArm()throws Exception{JSONObject e=e(),f=f(e);f.getJSONArray("broadcasts").put(new JSONObject(e.toString()).put("id","duplicate-notice"));assertEquals(2,ReminderPolicy.plan(f,p(),NOW,ZoneId.of("UTC")).size());e.getJSONObject("broadcast").remove("programStartAt");e.getJSONObject("broadcast").remove("scheduledAt");assertTrue(ReminderPolicy.plan(f(e),p(),NOW,ZoneId.of("UTC")).isEmpty());}
 @Test public void newerCancellationOverridesOldReservationAndPastClockDoesNotClaimLive()throws Exception{JSONObject e=e(),f=f(e),cancelled=new JSONObject(e.toString()).put("id","new-cancellation");cancelled.getJSONObject("broadcast").put("status","cancelled").put("statusCheckedAt",Instant.ofEpochMilli(NOW+1000).toString());f.getJSONArray("broadcasts").put(cancelled);assertTrue(ReminderPolicy.plan(f,p(),NOW,ZoneId.of("UTC")).isEmpty());ReminderMessage m=ReminderMessage.create(f(e),p(),e,"broadcast",NOW,0,NOW,ZoneId.of("UTC"));assertTrue(m.title.contains("配信予約時刻"));assertFalse(m.title.contains("開始しました"));assertFalse(ReminderSettings.due(e,p(),"broadcast",ReminderPolicy.eventAt(e,"broadcast"),0,ReminderPolicy.eventAt(e,"broadcast")+11*60000));}
 @Test public void validatorRejectsClockPollutionAndDuplicateIdentity()throws Exception{JSONObject e=e();FeedValidator.encode(f(e));e.put("startAt","2026-10-23T04:00:00Z");try{FeedValidator.encode(f(e));fail();}catch(JSONException expected){}e=e();JSONObject f=f(e);f.getJSONArray("broadcasts").put(e);try{FeedValidator.encode(f);fail();}catch(JSONException expected){}}
}
